// Module 11 evidence: installs one real appliance from a package generated by the dev stack for a
// custom-REST PSA instance that points at a fake PSA served over TLS (private CA) on this host, enters
// the credentials and the CA on the appliance's local admin page, runs the real connection test there,
// and captures: the appliance's credentials/connection page, the Control Plane's Integrations page,
// the PSA instance page with the test history and the deployment health page. Removes the appliance
// afterwards. Requires the dev API on the host address (AGENT_GATEWAY_HOST=0.0.0.0). Usage: node scripts/screenshots-m11.mjs
import { spawn, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-11/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const hostIp = sh(`ip -4 route get 1.1.1.1 | awk '{for(i=1;i<=NF;i++) if($i=="src") print $(i+1)}'`).out;

// ---- fake PSA (custom REST) over TLS with a self-signed CA, in its own process ----
// (this script uses synchronous shell calls, which would stall an in-process server during the appliance's test)
const API_KEY = `demo-${Math.random().toString(36).slice(2, 10)}`;
const caPath = join(realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m11ca-'))), 'ca.pem');
const fake = spawn(process.execPath, [fileURLToPath(new URL('./fake-psa.mjs', import.meta.url)), hostIp, API_KEY, caPath], { stdio: ['ignore', 'pipe', 'inherit'] });
const fakeLog = [];
const port = await new Promise((resolve, reject) => {
  fake.stdout.on('data', (d) => {
    for (const line of String(d).split(/\r?\n/).filter(Boolean)) {
      fakeLog.push(line);
      const m = /^PORT (\d+)$/.exec(line);
      if (m) resolve(Number(m[1]));
    }
  });
  fake.on('exit', (code) => reject(new Error(`fake PSA exited with ${code}`)));
});
const caPem = readFileSync(caPath, 'utf8');

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};

const client = (await api('GET', '/clients?status=active&pageSize=50')).items.find((c) => c.code !== 'CL-00001');
const services = await api('GET', `/clients/${client.id}/services`);
const instance = await api('POST', '/psa-instances', {
  clientId: client.id, providerKey: 'custom_rest', displayName: `${client.displayName} — Demo PSA ${Date.now().toString(36)}`, authMethod: 'api_key',
  config: { baseUrl: `https://${hostIp}:${port}/api`, healthPath: '/health', apiKeyHeader: 'X-API-Key' }, enabledServiceIds: services.filter((s) => s.requiresPsa).map((s) => s.id),
});
const dep = await api('POST', '/deployments', { clientId: client.id, psaInstanceId: instance.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module11-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m11-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
writeFileSync(join(winTmp, 'ca.pem'), caPem);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m11shots/${project}`;
const adminPort = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unix = (p) => sh(`wslpath -a '${p}'`).out;
const adminBase = `http://127.0.0.1:${adminPort}`;
const curl = (args) => sh(`curl -s -o /tmp/psacc-m11shots/body -w '%{http_code}' -b /tmp/psacc-m11shots/jar -c /tmp/psacc-m11shots/jar ${args}; echo; cat /tmp/psacc-m11shots/body`, 60_000).out;

try {
  let r = sh(`rm -rf /tmp/psacc-m11shots && mkdir -p /tmp/psacc-m11shots && cd /tmp/psacc-m11shots && unzip -q "${unix(join(winTmp, pkg.fileName))}" && cd ${project} && cp config/edge.env.template .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  for (let n = 0; n < 90; n++) {
    const d = await api('GET', `/deployments/${dep.id}`);
    if (d.lifecycleState === 'verified') break;
    await sleep(2000);
  }
  // Local admin: first-run setup, credentials + CA, test → tls_error without CA? (CA entered first here), then verified.
  const pw = `demo-${dep.code}-local-admin-pass`;
  curl(`-X POST --data-urlencode username=localadmin --data-urlencode password=${pw} --data-urlencode confirm=${pw} ${adminBase}/setup`);
  const form = curl(`${adminBase}/credentials`);
  const token = /name="csrf" value="([^"]+)"/.exec(form)[1];
  curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`); // without credentials: not_configured
  curl(`-X POST --data-urlencode csrf=${token} --data-urlencode field_apiKey=${API_KEY} ${adminBase}/credentials`);
  curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`); // without the CA: tls_error
  curl(`-X POST --data-urlencode csrf=${token} --data-urlencode "field_tlsCaCertificate@${unix(join(winTmp, 'ca.pem'))}" ${adminBase}/credentials`);
  const tested = curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`);
  if (!tested.includes('Connection verified')) {
    const m = /<div class="alert (?:ok|error)"[^>]*>([\s\S]*?)<\/div>/.exec(tested);
    const rows = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-postgres sh -c 'PGPASSWORD="$(cat /run/secrets/postgres_owner_password)" psql -h 127.0.0.1 -U psa_edge_owner -d psa_edge -qtAX -c "SELECT tested_at, code, http_status, latency_ms, detail FROM psa_connection_tests ORDER BY id"'`).out;
    const reach = sh(`docker run --rm --network ${project}_edge-egress curlimages/curl:8.11.1 -sk -m 8 -o /dev/null -w 'egress-network: HTTP %{http_code} in %{time_total}s' https://${hostIp}:${port}/api/health`).out;
    throw new Error(`the appliance test did not verify: ${(m?.[1] ?? tested.slice(-800)).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()}\n--- appliance rows:\n${rows}\n--- ${reach}\n--- fake server log: ${fakeLog.slice(-5).join(' | ')}`);
  }

  // The appliance's own page, signed in as the local administrator (loopback of the Docker host = this machine).
  const edge = await browser.newContext({ viewport: { width: 1200, height: 900 }, deviceScaleFactor: 2 });
  const ep = await edge.newPage();
  await ep.goto(`http://localhost:${adminPort}/login`);
  await ep.getByLabel('User name').fill('localadmin');
  await ep.getByLabel('Password').fill(pw);
  await ep.getByRole('button', { name: 'Sign in' }).click();
  await ep.goto(`http://localhost:${adminPort}/credentials`, { waitUntil: 'networkidle' });
  await shot(ep, '01-appliance-credentials-and-tests');
  await ep.goto(`http://localhost:${adminPort}/`, { waitUntil: 'networkidle' });
  await shot(ep, '02-appliance-dashboard', false);
  await edge.close();

  for (let n = 0; n < 60; n++) {
    if ((await api('GET', `/psa-instances/${instance.id}`)).connectionStatus === 'succeeded') break;
    await sleep(2000);
  }
  await page.goto(`${base}/integrations`, { waitUntil: 'networkidle' });
  await shot(page, '03-integrations-fleet');
  await page.goto(`${base}/integrations?connectionStatus=succeeded`, { waitUntil: 'networkidle' });
  await shot(page, '04-integrations-verified-only', false);
  await page.goto(`${base}/psa/${instance.id}`, { waitUntil: 'networkidle' });
  await shot(page, '05-psa-instance-connection-history');
  await page.goto(`${base}/deployments/${dep.id}/health`, { waitUntil: 'networkidle' });
  await shot(page, '06-deployment-health');
  await page.setViewportSize({ width: 375, height: 812 });
  await page.goto(`${base}/integrations`, { waitUntil: 'networkidle' });
  await shot(page, '07-integrations-mobile', false);
  await page.setViewportSize({ width: 1440, height: 900 });

  const tests = await api('GET', `/psa-instances/${instance.id}/connection-tests`);
  writeFileSync(`${outDir}connection-tests-api-sample.json`, JSON.stringify(tests.map((t) => ({ ...t, deployment: { ...t.deployment, id: '(omitted)' } })), null, 2));
  r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-postgres sh -c 'PGPASSWORD="$(cat /run/secrets/postgres_owner_password)" psql -h 127.0.0.1 -U psa_edge_owner -d psa_edge -qtAX' <<'SQL'\nSELECT tested_at, tested_by, ok, code, http_status, latency_ms, left(detail, 80) FROM psa_connection_tests ORDER BY id;\nSQL`);
  writeFileSync(`${outDir}appliance-psa-connection-tests.txt`, `$ psql (as the database owner, on the appliance)\nSELECT tested_at, tested_by, ok, code, http_status, latency_ms, left(detail, 80) FROM psa_connection_tests ORDER BY id;\n--\n${r.out || r.err}\n`);
  if ((r.out + r.err).includes(API_KEY)) throw new Error('api key leaked into the appliance test history');
} finally {
  sh(`cd ${work} && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m11shots`);
  rmSync(winTmp, { recursive: true, force: true });
  fake.kill('SIGTERM');
  rmSync(caPath, { force: true });
  await browser.close();
}
